// Returns: 0 = can buy, 1 = can't afford, 2 = unavailable (owned / maxed / full).
// Fills the short status text ("90g", "OWNED", "MAX"...) and the price.
static uint16_t OfferState(uint16_t off, char *stat, uint16_t *costOut)
{
    const Offer *of = &rc_kOffer[off];
    uint16_t cost = 0, lv = 0, mx = 0;
    int16_t  n;

    stat[0]  = 0;
    *costOut = 0;

    if(of->kind == K_STAT)
    {
        switch(of->idx)
        {
            case ST_DMG:   lv = rc_lvDmg;   mx = 6; cost = 30 + 25 * lv; break;
            case ST_RATE:  lv = rc_lvRate;  mx = 5; cost = 30 + 25 * lv; break;
            case ST_SPEED: lv = rc_lvSpeed; mx = 4; cost = 25 + 20 * lv; break;
            case ST_GOLD:  lv = rc_lvGold;  mx = 4; cost = 40 + 30 * lv; break;
            case ST_HEART:
                lv = rc_maxHp - RC_START_HEARTS;
                mx = RC_MAX_HEARTS - RC_START_HEARTS;
                cost = 70 + 50 * lv;
                break;
            default:                                            // ST_HEAL
                if(rc_hp >= rc_maxHp) { rc_Cat(stat, 0, "FULL", 4); return 2; }
                cost = 20;
                n = rc_Itoa(stat, cost);
                rc_Cat(stat, n, "g", 1);
                *costOut = cost;
                return (rc_gold >= cost) ? 0 : 1;
        }

        if(lv >= mx) { rc_Cat(stat, 0, "MAX", 3); return 2; }
    }
    else if(of->kind == K_TRAIT)
    {
        if(rc_traits & (1u << of->idx)) { rc_Cat(stat, 0, "OWNED", 5); return 2; }
        cost = rc_kTraitCost[of->idx];
    }
    else if(of->kind == K_STAFF)
    {
        if(rc_staffOwned & (1u << of->idx)) { rc_Cat(stat, 0, "OWNED", 5); return 2; }
        cost = rc_kStaffCost[of->idx];
    }
    else
    {
        if(rc_itemOwned & (1u << of->idx)) { rc_Cat(stat, 0, "OWNED", 5); return 2; }
        cost = rc_kItemCost[of->idx];
    }

    n = rc_Itoa(stat, cost);
    rc_Cat(stat, n, "g", 1);
    *costOut = cost;
    return (rc_gold >= cost) ? 0 : 1;
}


// Three distinct random offers from whatever is still available.
static void RollCards(void)
{
    uint16_t pool[NUM_OFFER], n = 0, i, k, cost;
    char     stat[16];

    for(i = 0; i < NUM_OFFER; i++)
        if(OfferState(i, stat, &cost) != 2) pool[n++] = i;

    for(i = 0; i < 3; i++)
    {
        if(n == 0)
        {
            rc_card[i].off  = CARD_NONE;
            rc_card[i].sold = 1;
            continue;
        }
        k = Rand16() % n;
        rc_card[i].off  = pool[k];
        rc_card[i].sold = 0;
        pool[k] = pool[--n];
    }
    rc_cardDirty = CD_ALL;
}


static uint16_t RerollCost(void)
{
    return (uint16_t)(15u + 10u * rc_rerolls);
}


static void DrawCard(uint16_t i)
{
    int16_t  x0 = (int16_t)(CARD_X0 + (int16_t)i * (CARD_W + CARD_GAP));
    int16_t  y0 = CARD_Y0;
    int16_t  x1 = (int16_t)(x0 + CARD_W - 1);
    int16_t  y1 = (int16_t)(y0 + CARD_H - 1);
    int16_t  cx = (int16_t)(x0 + CARD_W / 2);
    bool     sel = (rc_cardSel == i);
    uint32_t fill = sel ? COLOR_CHARCOAL : COLOR_TETRIS_GRID;
    uint32_t band;
    const Offer *of;
    const char *kindName;
    char     stat[16], line[16];
    uint16_t st, cost, k, n;
    int16_t  y;

    Graphics_FillRect(x0, y0, x1, y1, sel ? C_CYAN : COLOR_CHARCOAL);       // border
    Graphics_FillRect(x0 + 2, y0 + 2, x1 - 2, y1 - 2, fill);

    if(rc_card[i].off == CARD_NONE)
    {
        rc_DrawSmall("sold out", cx, (int16_t)(y0 + CARD_H / 2), C_DKGRAY, fill);
        return;
    }

    of = &rc_kOffer[rc_card[i].off];
    switch(of->kind)
    {
        case K_STAT:  kindName = "UPGRADE"; band = COLOR_CHARCOAL; break;
        case K_TRAIT: kindName = "TRAIT";   band = COLOR_PURPLE; break;
        case K_STAFF: kindName = "STAFF";   band = COLOR_OLIVE; break;
        default:      kindName = "MAGIC";   band = COLOR_TEAL; break;
    }

    Graphics_FillRect(x0 + 2, y0 + 2, x1 - 2, y0 + 17, band);
    rc_DrawSmall(kindName, cx, (int16_t)(y0 + 10), C_WHITE, band);

    rc_DrawSmall(of->name, cx, (int16_t)(y0 + 32), C_WHITE, fill);

    // Description: lines separated by '|'
    y = (int16_t)(y0 + 54);
    n = 0;
    for(k = 0; ; k++)
    {
        char ch = of->desc[k];

        if(ch == '|' || ch == 0)
        {
            line[n] = 0;
            rc_DrawSmall(line, cx, y, C_GRAY, fill);
            y = (int16_t)(y + 15);
            n = 0;
            if(ch == 0) break;
        }
        else if(n < 14)
            line[n++] = ch;
    }

    // Price / state
    if(rc_card[i].sold)
    {
        rc_DrawText("SOLD", cx, (int16_t)(y1 - 16), C_DKGRAY);
    }
    else
    {
        st  = OfferState(rc_card[i].off, stat, &cost);
        rc_DrawTextEx(stat, cx, (int16_t)(y1 - 16),
                   (st == 0) ? C_GREEN : (st == 1) ? C_BAD : C_GRAY, fill, false);
    }
}


static void DrawReroll(void)
{
    char     buf[16];
    int16_t  n;
    bool     sel = (rc_cardSel == 3);
    uint32_t fill = sel ? COLOR_CHARCOAL : COLOR_TETRIS_GRID;
    uint16_t cost = RerollCost();

    Graphics_FillRect(RR_X0, RR_Y0, RR_X1, RR_Y1, sel ? C_CYAN : COLOR_CHARCOAL);
    Graphics_FillRect(RR_X0 + 2, RR_Y0 + 2, RR_X1 - 2, RR_Y1 - 2, fill);

    n  = rc_Cat(buf, 0, "REROLL  ", 8);
    n += rc_Itoa(buf + n, cost);
    rc_Cat(buf, n, "g", 1);
    rc_DrawTextEx(buf, (RR_X0 + RR_X1) / 2, (RR_Y0 + RR_Y1) / 2,
               (rc_gold >= cost) ? C_WHITE : C_BAD, fill, false);
}


