void rc_CardsRender(void)
{
    uint16_t i;

    for(i = 0; i < 3; i++)
        if(rc_cardDirty & (1u << i)) DrawCard(i);
    if(rc_cardDirty & CD_REROLL) DrawReroll();
    if(rc_cardDirty & CD_GOLD)   DrawCardsGold();
    if(rc_cardDirty & CD_MSG)    DrawCardMsg();

    rc_cardDirty = 0;
}


void rc_EnterCards(void)
{
    rc_mode      = MODE_CARDS;
    rc_dirtyFull = true;
    rc_cardSel   = 1;
    rc_cardMsg   = 0;
    rc_rerolls   = 0;
    rc_stX = rc_stY = 1;                  // ignore a stick that is already pushed
    RollCards();
    rc_Sfx(&sfx_level_up);
}


// The merchant reuses the card screen as his shop.
void rc_EnterShop(void)
{
    rc_shopMode = 1;
    rc_lvPending++;
    rc_EnterCards();
}


static void BuyCard(uint16_t i)
{
    const Offer *of;
    char         stat[16];
    uint16_t     cost, st;

    rc_cardDirty |= CD_MSG;

    if(rc_card[i].off == CARD_NONE || rc_card[i].sold)
    {
        rc_cardMsg = 3;
        rc_Sfx(&sfx_menu_bump);
        return;
    }

    of = &rc_kOffer[rc_card[i].off];
    st = OfferState(rc_card[i].off, stat, &cost);

    if(st == 2)         { rc_cardMsg = 3; rc_Sfx(&sfx_menu_bump); return; }
    if(rc_gold < cost)   { rc_cardMsg = 2; rc_Sfx(&sfx_menu_bump); return; }

    rc_gold -= cost;

    switch(of->kind)
    {
        case K_STAT:
            switch(of->idx)
            {
                case ST_DMG:   rc_lvDmg++;   break;
                case ST_RATE:  rc_lvRate++;  break;
                case ST_SPEED: rc_lvSpeed++; break;
                case ST_GOLD:  rc_lvGold++;  break;
                case ST_HEART: rc_maxHp++; rc_hp++; break;
                default:       rc_hp++;      break;              // heal
            }
            break;

        case K_TRAIT:
            rc_traits |= (1u << of->idx);
            break;

        case K_STAFF:
            rc_staffOwned |= (1u << of->idx);
            rc_equip       = of->idx;
            break;

        default:                                                // K_ITEM
            rc_itemOwned |= (1u << of->idx);
            rc_equip      = NUM_STAFF + of->idx;
            break;
    }

    rc_card[i].sold = 1;
    rc_cardMsg      = 1;
    rc_cardDirty   |= CD_GOLD | CD_REROLL | 0x07;                // prices may now be affordable / not
    rc_Sfx(&sfx_coin);
}


static void RerollCards(void)
{
    uint16_t cost = RerollCost();

    rc_cardDirty |= CD_MSG;

    if(rc_gold < cost)
    {
        rc_cardMsg = 2;
        rc_Sfx(&sfx_menu_bump);
        return;
    }

    rc_gold -= cost;
    rc_rerolls++;
    RollCards();
    rc_cardMsg    = 4;
    rc_cardDirty |= CD_GOLD | CD_REROLL | CD_MSG;
    rc_Sfx(&sfx_menu_select);
}


static void LeaveCards(void)
{
    rc_Sfx(&sfx_menu_back);

    if(rc_lvPending) rc_lvPending--;

    if(rc_lvPending > 0)                 // more level-ups waiting: next set of cards
    {
        rc_rerolls   = 0;
        rc_cardMsg   = 0;
        rc_cardSel   = 1;
        rc_dirtyFull = true;
        RollCards();
    }
    else
    {
        rc_shopMode  = 0;
        rc_mode      = MODE_PLAY;
        rc_dirtyFull = true;
    }
}


void rc_UpdateCards(void)
{
    int16_t  sx = rc_StickEdge(g_joy.dx, &rc_stX);
    uint16_t old = rc_cardSel;

    (void)rc_StickEdge(g_joy.dy, &rc_stY);

    if(g_dpad.dPressed) { LeaveCards(); return; }

    if(g_dpad.lPressed || sx < 0)
        rc_cardSel = (rc_cardSel + 3u) % 4u;
    else if(g_dpad.rPressed || sx > 0)
        rc_cardSel = (rc_cardSel + 1u) % 4u;

    if(rc_cardSel != old)
    {
        rc_cardDirty |= (old == 3 ? CD_REROLL : (1u << old)) |
                       (rc_cardSel == 3 ? CD_REROLL : (1u << rc_cardSel));
        rc_Sfx(&sfx_menu_move);
    }

    if(g_dpad.uPressed || g_joy.btnPressed)
    {
        if(rc_cardSel < 3) BuyCard(rc_cardSel);
        else              RerollCards();
    }
}


